            NemesisCape(
                "PiFengFR1>PiFengFR7"
            ),
        },
        Colliders = HumanoidColliders(1.648f),
    };

    // Her cape hangs in a grid of columns eight bones long off both arms, so the Skirt
    // preset's soft tip under a firmer root sends every turn rippling down them. An even
    // stiffness root to tip moves each column as one panel, double gravity keeps it from
    // floating, and the extra drag settles it.
    internal static SpringChainSpec NemesisCape(params string[] roots)
    {
        var spec = SpringPresets.Skirt(roots);
        spec.Gravity = 1f;
        spec.Stiffness = 2.5f;
        spec.TipStiffness = 2.5f;
        spec.Drag = 0.6f;
        return spec;
    }
}
